 * Cell address helpers: encoding columns as numbers, canonical formatting,
 * and validating strings as addresses inside the addressable range
 * (columns A..ZZ, rows 1..999).
 */

// letters (already upper-cased) -> column number, A=1 .. Z=26, AA=27 .. ZZ=702
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

export function numToCol(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const first = Math.floor((n - 1) / 26)
  const second = ((n - 1) % 26) + 1
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

// Parses `word` (expected already upper-cased) as a strict address: 1-2
// letters, 1-3 digits, row >= 1. Returns {col,row} or null when it is not a
// valid address (outside the addressable range).
const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

export function parseAddressStrict(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = colToNum(m[1])
  return { col, row }
}

export function canonAddress({ col, row }) {
  return numToCol(col) + String(row)
}
"}

