chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-HFgF2U/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, producing an AST.
 *
 * Grammar (loosest to tightest precedence):
 *   comparison  := additive ( (=|<>|<|<=|>|>=) additive )*
 *   additive    := multiplicative ( (+|-) multiplicative )*
 *   multiplicative := power ( (*|/) power )*
 *   power       := unary ( '^' power )?         // right-assoc
 *   unary       := ('+'|'-') unary | atom        // binds tighter than '^'
 *   atom        := NUMBER | range | TRUE | FALSE | call | address | '(' expr ')'
 *   range       := WORD ':' WORD                 // accepted anywhere syntactically;
 *                                                 // only meaningful directly as a call argument
 *   call        := WORD '(' expr (',' expr)* ')'
 */

import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (t.type !== type) throw new ParseError(`expected ${type}, got ${t.type}`)
    return t
  }

  parseFormula() {
    const e = this.parseExpr()
    this.expect('EOF')
    return e
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek().type === 'OP' && COMPARISON_OPS.has(this.peek().op)) {
      const op = this.next().op
      const right = this.parseAdditive()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek().type === 'OP' && (this.peek().op === '+' || this.peek().op === '-')) {
      const op = this.next().op
      const right = this.parseMultiplicative()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek().type === 'OP' && (this.peek().op === '*' || this.peek().op === '/')) {
      const op = this.next().op
      const right = this.parsePower()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek().type === 'OP' && this.peek().op === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'Bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek().type === 'OP' && (this.peek().op === '+' || this.peek().op === '-')) {
      const op = this.next().op
      const expr = this.parseUnary()
      return { type: 'Unary', op, expr }
    }
    return this.parseAtom()
  }

  parseAtom() {
    const t = this.peek()
    if (t.type === 'NUM') {
      this.next()
      return { type: 'Num', value: t.value }
    }
    if (t.type === 'LPAREN') {
      this.next()
      const e = this.parseExpr()
      this.expect('RPAREN')
      return e
    }
    if (t.type === 'WORD') {
      // Look ahead for a range: WORD ':' WORD
      if (this.peek(1).type === 'COLON' && this.peek(2).type === 'WORD') {
        const a = this.next().text
        this.next() // colon
        const b = this.next().text
        return { type: 'Range', a, b }
      }
      const upper = t.text.toUpperCase()
      if (upper === 'TRUE') {
        this.next()
        return { type: 'Bool', value: true }
      }
      if (upper === 'FALSE') {
        this.next()
        return { type: 'Bool', value: false }
      }
      if (this.peek(1).type === 'LPAREN') {
        this.next() // word
        this.next() // lparen
        const args = [this.parseExpr()]
        while (this.peek().type === 'COMMA') {
          this.next()
          args.push(this.parseExpr())
        }
        this.expect('RPAREN')
        return { type: 'Call', name: upper, args }
      }
      this.next()
      return { type: 'Address', word: t.text }
    }
    throw new ParseError(`unexpected token ${t.type}`)
  }
}

// Returns the AST, or null when the formula body does not parse.
export function parseFormula(src) {
  try {
    const tokens = tokenize(src)
    const parser = new Parser(tokens)
    return parser.parseFormula()
  } catch (e) {
    if (e instanceof LexError || e instanceof ParseError) return null
    throw e
  }
}
"}

