 * Formula and literal evaluation, with memoized/cycle-safe cell lookups.
 */

import { parseAddressStrict, canonAddress, numToCol } from './address.js'
import { parseLiteral } from './literal.js'
import { num, bool, err, arithValue, condToBool, compareValues, finiteNum } from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

export class Evaluator {
  constructor(cellsByAddr) {
    this.cells = cellsByAddr // Map addr -> { content, ast, parseOk }
    this.cache = new Map()
    this.visiting = new Set()
  }

  evalCell(addr) {
    if (this.cache.has(addr)) return this.cache.get(addr)
    const cell = this.cells.get(addr)
    if (!cell) {
      const v = num(0)
      this.cache.set(addr, v)
      return v
    }
    if (this.visiting.has(addr)) {
      return err('#CYCLE!')
    }
    this.visiting.add(addr)
    let result
    try {
      result = this.evalContent(cell)
    } finally {
      this.visiting.delete(addr)
    }
    this.cache.set(addr, result)
    return result
  }

  evalContent(cell) {
    if (cell.content.startsWith('=')) {
      if (!cell.parseOk) return err('#ERR!')
      return this.evalNode(cell.ast)
    }
    return parseLiteral(cell.content)
  }

  evalNode(node) {
    switch (node.type) {
      case 'Num':
        return num(node.value)
      case 'Bool':
        return bool(node.value)
      case 'Address': {
        const parsed = parseAddressStrict(node.word.toUpperCase())
        if (!parsed) return err('#REF!')
        return this.evalCell(canonAddress(parsed))
      }
      case 'Range':
        // A range is only meaningful directly as a function argument.
        return err('#ERR!')
      case 'Unary': {
        const v = this.evalNode(node.expr)
        const a = arithValue(v)
        if (a.type === 'error') return a
        const val = node.op === '-' ? -a.value : a.value
        return finiteNum(val)
      }
      case 'Bin': {
        const l = this.evalNode(node.left)
        const r = this.evalNode(node.right)
        if (COMPARISON_OPS.has(node.op)) return this.evalCompare(node.op, l, r)
        return this.evalArith(node.op, l, r)
      }
      case 'Call':
        return this.evalCall(node)
      default:
        throw new Error('unreachable node type ' + node.type)
    }
  }

  evalArith(op, l, r) {
    const L = arithValue(l)
    if (L.type === 'error') return L
    const R = arithValue(r)
    if (R.type === 'error') return R
    let result
    switch (op) {
      case '+':
        result = L.value + R.value
        break
      case '-':
        result = L.value - R.value
        break
      case '*':
        result = L.value * R.value
        break
      case '/':
        if (R.value === 0) return err('#DIV/0!')
        result = L.value / R.value
        break
      case '^':
        result = Math.pow(L.value, R.value)
        break
      default:
        throw new Error('unreachable op ' + op)
    }
    return finiteNum(result)
  }

  evalCompare(op, l, r) {
    if (l.type === 'error') return l
    if (r.type === 'error') return r
    const cmp = compareValues(l, r)
    let result
    switch (op) {
      case '=':
        result = cmp === 0
        break
      case '<>':
        result = cmp !== 0
        break
      case '<':
        result = cmp < 0
        break
      case '<=':
        result = cmp <= 0
        break
      case '>':
        result = cmp > 0
        break
      case '>=':
        result = cmp >= 0
        break
      default:
        throw new Error('unreachable op ' + op)
    }
    return bool(result)
  }

