  expandArg(node) {
    if (node.type === 'Range') return this.expandRange(node)
    return [this.evalNode(node)]
  }

  expandRange(node) {
    const p1 = parseAddressStrict(node.a.toUpperCase())
    const p2 = parseAddressStrict(node.b.toUpperCase())
    if (!p1 || !p2) return [err('#REF!')]
    const colMin = Math.min(p1.col, p2.col)
    const colMax = Math.max(p1.col, p2.col)
    const rowMin = Math.min(p1.row, p2.row)
    const rowMax = Math.max(p1.row, p2.row)
    const values = []
    for (let c = colMin; c <= colMax; c++) {
      for (let rw = rowMin; rw <= rowMax; rw++) {
        values.push(this.evalCell(numToCol(c) + String(rw)))
      }
    }
    return values
  }

  evalCall(node) {
    const name = node.name
    const args = node.args
    switch (name) {
      case 'SUM':
      case 'MIN':
      case 'MAX':
      case 'AVG':
      case 'COUNT': {
        if (args.length < 1) return err('#ERR!')
        const all = []
        for (const a of args) all.push(...this.expandArg(a))
        return this.aggregate(name, all)
      }
      case 'ABS': {
        if (args.length !== 1) return err('#ERR!')
        const list = this.expandArg(args[0])
        return this.absFn(list)
      }
      case 'IF': {
        if (args.length !== 3) return err('#ERR!')
        const condList = this.expandArg(args[0])
        const cond = toSingle(condList)
        const cb = condToBool(cond)
        if (cb.type === 'error') return cb
        const branch = cb.value ? args[1] : args[2]
        const list = this.expandArg(branch)
        return toSingle(list)
      }
      default:
        return err('#NAME?')
    }
  }

  aggregate(name, values) {
    if (name === 'COUNT') {
      for (const v of values) {
        if (v.type === 'error') return v
      }
      let c = 0
      for (const v of values) if (v.type === 'number') c++
      return num(c)
    }
    const nums = []
    for (const v of values) {
      const a = arithValue(v)
      if (a.type === 'error') return a
      nums.push(a.value)
    }
    if (name === 'SUM') return finiteNum(nums.reduce((s, x) => s + x, 0))
    if (name === 'MIN') return finiteNum(Math.min(...nums))
    if (name === 'MAX') return finiteNum(Math.max(...nums))
    if (name === 'AVG') return finiteNum(nums.reduce((s, x) => s + x, 0) / nums.length)
    throw new Error('unreachable aggregate ' + name)
  }

  absFn(list) {
    if (list.length === 1) {
      const a = arithValue(list[0])
      if (a.type === 'error') return a
      return finiteNum(Math.abs(a.value))
    }
    for (const v of list) {
      if (v.type === 'error') return v
    }
    return err('#VALUE!')
  }
}

function toSingle(list) {
  if (list.length === 1) return list[0]
  for (const v of list) {
    if (v.type === 'error') return v
  }
  return err('#VALUE!')
}
"}

