  list.sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))
  return list
}

function addAddr(map, parsed) {
  const addr = canonAddress(parsed)
  if (!map.has(addr)) map.set(addr, { addr, col: parsed.col, row: parsed.row })
