/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { parseFormula } from './parser.js'
import { Evaluator } from './evaluator.js'
import { formatValue } from './values.js'
import { collectDeps } from './deps.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = argv[0]

  const input = fs.readFileSync(0, 'utf8')

  let declared
  try {
    declared = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const cellsByAddr = new Map()
  for (const c of declared) {
    let ast = null
    let parseOk = false
    if (c.content.startsWith('=')) {
      ast = parseFormula(c.content.slice(1))
      parseOk = ast !== null
    }
    cellsByAddr.set(c.addr, { content: c.content, ast, parseOk })
  }

  const ordered = [...declared].sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))

  const out = []
  if (mode === 'values') {
    const evaluator = new Evaluator(cellsByAddr)
    for (const c of ordered) {
      const v = evaluator.evalCell(c.addr)
      out.push(`${c.addr}=${formatValue(v)}`)
    }
  } else {
    for (const c of ordered) {
      const cell = cellsByAddr.get(c.addr)
      let depsStr = ''
      if (cell.content.startsWith('=') && cell.parseOk) {
        const deps = collectDeps(cell.ast)
        depsStr = deps.map((d) => ' ' + d.addr).join('')
      }
      out.push(`${c.addr}:${depsStr}`)
    }
  }

  process.stdout.write(out.length > 0 ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

